// @domain: awareness
//! The store trait every generated API reads and writes through (#4478). Settings pick
//! the backend; the door rules sit above it, so no backend can skip them.
//! Generated by athena-gen from its template — DO NOT EDIT; change the generator.

use crate::model::{ClassDef, GRAPH_PREFIX, NS};
use crate::settings::Settings;
use serde_json::{json, Map, Value};

/// One row as the API serves it: name, label, status, then every field the shape declares.
pub type Row = Map<String, Value>;

pub trait RowStore: Send + Sync {
    /// A page of rows in the store's order (sorted within the page), and the total count.
    fn list(&self, class: &ClassDef, limit: usize, offset: usize) -> Result<(Vec<Row>, usize), String>;
    /// One row by name, or None.
    fn get(&self, class: &ClassDef, name: &str) -> Result<Option<Row>, String>;
    /// Is there any row with this IRI, in any graph (a link's target check)?
    fn exists(&self, iri: &str) -> Result<bool, String>;
    /// How many versions of a row are kept.
    fn version_count(&self, of_row: &str) -> Result<usize, String>;
    /// One atomic write in one graph: for each named field, drop every stored value and
    /// write the given ones; `type_of` adds the rdf:type; `whole` drops the row first.
    fn write(&self, graph: &str, subject: &str, type_of: Option<&str>, fields: &[(String, Vec<Cell>)], whole: bool) -> Result<(), String>;
    /// Remove every triple of a row in its graph.
    fn delete(&self, graph: &str, subject: &str) -> Result<(), String>;
    /// #4524 — a page of the rows `viewer` may see, and THEIR count (the total of all
    /// rows would leak how many other people's rows exist): rows it owns, plus rows a
    /// Read or Write Permission names for it (the row, its owner, or the whole graph).
    fn list_seen_by(&self, class: &ClassDef, limit: usize, offset: usize, viewer: &str) -> Result<(Vec<Row>, usize), String>;
    /// One row by name if `viewer` may see it; None otherwise (never "exists, but not yours").
    fn get_seen_by(&self, class: &ClassDef, name: &str, viewer: &str) -> Result<Option<Row>, String>;    /// #4744 — a page of the rows that match `w` (and that `viewer` may see, when given),
    /// with the count of all matches: the filter runs in the store, before the page is cut.
    fn list_where(&self, class: &ClassDef, limit: usize, offset: usize, viewer: Option<&str>, w: &Where) -> Result<(Vec<Row>, usize), String>;
}

/// #4744 — one filter for every collection: each `eq` field holds the value (a literal
/// equal to it, or a link whose name it is), and `q` is found in some literal of the row.
#[derive(Debug, Default, Clone, PartialEq, Eq)]
pub struct Where {
    pub eq: Vec<(String, String)>,
    pub q: Option<String>,
    /// `<field>.lt=` / `<field>.gt=`: the field's value compared as a string (ISO times sort as text)
    pub bounds: Vec<(String, &'static str, String)>,
    /// `sort=<field>` or `sort=-<field>` (newest first): (field, descending)
    pub sort: Option<(String, bool)>,
}

fn sparql_str(v: &str) -> String {
    format!("\"{}\"", v.replace('\\', "\\\\").replace('"', "\\\"").replace('\n', "\\n").replace('\r', "\\r"))
}

/// The graph pattern for `w`, over the row `?s` in `graph`.
pub fn where_pattern(w: &Where, graph: &str) -> String {
    let mut out = String::new();
    for (i, (field, value)) in w.eq.iter().enumerate() {
        let v = sparql_str(value);
        out.push_str(&format!(
            "GRAPH <{graph}> {{ ?s <{NS}{field}> ?w{i} }} \
             FILTER(STR(?w{i}) = {v} || (isIRI(?w{i}) && (STRENDS(STR(?w{i}), CONCAT(\"#\", {v})) || STRENDS(STR(?w{i}), CONCAT(\"/\", {v}))))) "
        ));
    }
    for (i, (field, op, value)) in w.bounds.iter().enumerate() {
        out.push_str(&format!(
            "GRAPH <{graph}> {{ ?s <{NS}{field}> ?b{i} }} FILTER(STR(?b{i}) {op} {}) ", sparql_str(value)
        ));
    }
    if let Some((field, _)) = &w.sort {
        out.push_str(&format!("OPTIONAL {{ GRAPH <{graph}> {{ ?s <{NS}{field}> ?ord }} }} "));
    }
    if let Some(q) = &w.q {
        out.push_str(&format!(
            "FILTER EXISTS {{ GRAPH <{graph}> {{ ?s ?qp ?qo }} FILTER(isLiteral(?qo) && CONTAINS(LCASE(STR(?qo)), LCASE({}))) }} ",
            sparql_str(q)
        ));
    }
    out
}

/// #4524 — the visibility filter, one pattern for list, count and get. `?s` is the row in
/// `graph`; `viewer` is the caller's Principal IRI. A Permission whose accessTo is a
/// member's Principal IRI opens everything that member owns.
pub fn seen_by(viewer: &str, graph: &str) -> String {
    format!(
        "OPTIONAL {{ GRAPH <{graph}> {{ ?s <{NS}ownedBy> ?own }} }} \
         FILTER( (BOUND(?own) && ?own = <{viewer}>) || EXISTS {{ GRAPH ?pg {{ ?perm a <{NS}Permission> ; <{NS}agent> <{viewer}> ; <{NS}accessTo> ?t ; <{NS}mode> ?m }} \
           FILTER( (STR(?t) = STR(?s) || (BOUND(?own) && STR(?t) = STR(?own)) || STR(?t) = \"{graph}\") \
                && (STR(?m) = \"http://www.w3.org/ns/auth/acl#Read\" || STR(?m) = \"http://www.w3.org/ns/auth/acl#Write\") ) }} )"
    )
}

pub use crate::rules::Cell;

fn term(c: &Cell) -> String {
    match c {
        Cell::Link(iri) => format!("<{iri}>"),
        Cell::Literal(v, dt) => {
            let esc = v.replace('\\', "\\\\").replace('"', "\\\"").replace('\n', "\\n").replace('\r', "\\r");
            match *dt {
                "string" | "" => format!("\"{esc}\""),
                other => format!("\"{esc}\"^^<http://www.w3.org/2001/XMLSchema#{other}>"),
            }
        }
    }
}

/// The SPARQL Update for one write (pure, so it is tested without a store).
pub fn write_update(graph: &str, subject: &str, type_of: Option<&str>, fields: &[(String, Vec<Cell>)], whole: bool) -> String {
    let mut ops = Vec::new();
    if whole {
        ops.push(format!("DELETE WHERE {{ GRAPH <{graph}> {{ <{subject}> ?p ?o }} }}"));
    }
    let mut inserts = Vec::new();
    if let Some(t) = type_of {
        inserts.push(format!("<{subject}> a <{NS}{t}> ."));
    }
    for (k, cells) in fields {
        if !whole {
            ops.push(format!("DELETE WHERE {{ GRAPH <{graph}> {{ <{subject}> <{NS}{k}> ?o }} }}"));
        }
        for c in cells {
            inserts.push(format!("<{subject}> <{NS}{k}> {} .", term(c)));
        }
    }
    if !inserts.is_empty() {
        ops.push(format!("INSERT DATA {{ GRAPH <{graph}> {{ {} }} }}", inserts.join(" ")));
    }
    ops.join(" ;\n")
}

/// A row's IRI from its name: `<kind>-<name>`, where kind is the class in kebab case
/// (StreamEvent → stream-event). The name read back is the name written (v1 requirement 6).
pub fn iri(class: &ClassDef, name: &str) -> String {
    format!("{NS}{}-{name}", class.kind)
}

pub fn name_of(class: &ClassDef, iri: &str) -> String {
    let local = iri.rsplit(['#', '/']).next().unwrap_or(iri);
    local.strip_prefix(&format!("{}-", class.kind)).unwrap_or(local).to_string()
}

/// Who runs the SPARQL: a remote endpoint (Fuseki here) or an embedded store in a
/// folder (#4493: no Fuseki at all). The row logic above it is the same for both, so
/// the same tests prove both.
pub trait Engine: Send + Sync {
    /// SELECT solutions, each as SPARQL-JSON bindings: var → {"type", "value"}.
    fn select(&self, query: &str) -> Result<Vec<Map<String, Value>>, String>;
    fn update(&self, update: &str) -> Result<(), String>;
    /// #4524 — the same SELECT as a SPARQL-JSON body: what the shared sign-in checker
    /// (chorus-oidc) reads. Sign-in therefore asks THIS store, embedded or remote,
    /// never a second endpoint.
    fn select_json(&self, query: &str) -> Result<String, String> {
        let rows = self.select(query)?;
        let vars: Vec<String> = rows.first().map(|r| r.keys().cloned().collect()).unwrap_or_default();
        Ok(json!({ "head": { "vars": vars }, "results": { "bindings": rows } }).to_string())
    }
    /// The embedded store itself, for the backup and restore drill; None for a remote one.
    fn as_embedded(&self) -> Option<&Embedded> {
        None
    }
    /// #4716 — the door, when writes go through it instead of to the store.
    fn as_door(&self) -> Option<&Door> {
        None
    }
}

/// #4716 — `store.kind = door`. Reads are SPARQL queries; every write is a
/// change sent to the door's `/batch` under this service's own token, so the
/// store's write password lives in the door alone.
pub struct Door {
    pub reads: Remote,
    pub door: String,
    /// a fixed token (tests), used when `token_command` is empty
    pub token: String,
    /// #4716 — the command that prints a current token. Service tokens live ~600 s
    /// and the command keeps a cache, so asking it on every write never sends an
    /// expired one and costs a file read when the cache is warm.
    pub token_command: String,
}

impl Engine for Door {
    fn select(&self, query: &str) -> Result<Vec<Map<String, Value>>, String> {
        self.reads.select(query)
    }
    fn update(&self, _update: &str) -> Result<(), String> {
        Err("store: a door store sends no SPARQL update; writes go through the door".into())
    }
    fn as_door(&self) -> Option<&Door> {
        Some(self)
    }
}

impl Door {
    /// One change to one graph, all of it or none of it (the door's batch).
    fn current_token(&self) -> String {
        if self.token_command.trim().is_empty() {
            return self.token.clone();
        }
        token_from_command(&self.token_command, TOKEN_WAIT)
    }

    pub fn batch(&self, graph: &str, lines: &[String]) -> Result<(), String> {
        let token = self.current_token();
        if token.trim().is_empty() {
            return Err("store: no service token for the door; nothing written".into());
        }
        if lines.is_empty() {
            return Ok(());
        }
        ureq::post(&format!("{}/batch", self.door.trim_end_matches('/')))
            .set("Authorization", &format!("Bearer {token}"))
            .set("x-target-graph", graph)
            .send_string(&lines.join("\n"))
            .map(|_| ())
            .map_err(|e| format!("store: the door refused the write: {e}"))
    }
}

/// #4716 — how long a write waits for the token command. A hung command must
/// not hang the write that asked: past this the write gets no token and refuses.
pub const TOKEN_WAIT: std::time::Duration = std::time::Duration::from_secs(10);

/// #4716 — the token a command prints, or "" when it fails, prints nothing, or
/// is still running after `wait` (it is stopped, and the caller refuses).
pub fn token_from_command(cmd: &str, wait: std::time::Duration) -> String {
    use std::io::Read;
    use std::process::{Command, Stdio};
    let Ok(mut child) = Command::new("sh").args(["-c", cmd])
        .stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::null()).spawn() else {
        return String::new();
    };
    let start = std::time::Instant::now();
    loop {
        match child.try_wait() {
            Ok(Some(status)) => {
                if !status.success() {
                    return String::new();
                }
                let mut out = String::new();
                if let Some(mut so) = child.stdout.take() {
                    let _ = so.read_to_string(&mut out);
                }
                return out.trim().to_string();
            }
            Ok(None) if start.elapsed() < wait => std::thread::sleep(std::time::Duration::from_millis(20)),
            _ => {
                let _ = child.kill();
                let _ = child.wait();
                return String::new();
            }
        }
    }
}

/// #4716 — the same change as `write_update`, as the door's batch lines
/// (`DEL s p ?o` / `INS s p o`). The door takes no predicate wildcard, so a whole
/// replace names the predicates the row has now (`existing`).
pub fn write_lines(subject: &str, type_of: Option<&str>, fields: &[(String, Vec<Cell>)], whole: bool, existing: &[String]) -> Vec<String> {
    let mut out = Vec::new();
    let mut del = |p: &str| {
        let l = format!("DEL\t<{subject}>\t<{p}>\t?o");
        if !out.contains(&l) { out.push(l); }
    };
    if whole {
        existing.iter().for_each(|p| del(p));
    } else {
        fields.iter().for_each(|(k, _)| del(&format!("{NS}{k}")));
    }
    if let Some(t) = type_of {
        out.push(format!("INS\t<{subject}>\t<http://www.w3.org/1999/02/22-rdf-syntax-ns#type>\t<{NS}{t}>"));
    }
    for (k, cells) in fields {
        for c in cells {
            out.push(format!("INS\t<{subject}>\t<{NS}{k}>\t{}", term(c)));
        }
    }
    out
}

pub struct Remote {
    pub endpoint: String,
    pub auth: Option<(String, String)>,
}

impl Engine for Remote {
    fn select(&self, query: &str) -> Result<Vec<Map<String, Value>>, String> {
        let text = sparql_body(&self.endpoint, &self.auth, query)?;
        let body: Value = serde_json::from_str(&text).map_err(|e| format!("store: {e}"))?;
        let rows = body["results"]["bindings"].as_array().cloned().unwrap_or_default();
        Ok(rows.into_iter().filter_map(|r| r.as_object().cloned()).collect())
    }
    fn update(&self, update: &str) -> Result<(), String> {
        sparql_update(&self.endpoint, &self.auth, update)
    }
}

/// Embedded Oxigraph (RocksDB in a folder). One process writes it at a time.
pub struct Embedded {
    store: oxigraph::store::Store,
}

impl Embedded {
    pub fn open(path: &str) -> Result<Self, String> {
        Ok(Embedded { store: oxigraph::store::Store::open(path).map_err(|e| format!("store {path}: {e}"))? })
    }
    #[cfg(test)]
    pub fn memory() -> Self {
        Embedded { store: oxigraph::store::Store::new().expect("in-memory store") }
    }
    /// Load a TriG dump (the move from another store, and the restore half of the drill).
    pub fn load_trig(&self, trig: &[u8]) -> Result<(), String> {
        self.store.load_from_slice(oxigraph::io::RdfFormat::TriG, trig).map_err(|e| format!("load: {e}"))
    }
    /// Dump every named graph as TriG (the backup half of the drill).
    pub fn dump_trig(&self) -> Result<Vec<u8>, String> {
        self.store.dump_to_writer(oxigraph::io::RdfSerializer::from_format(oxigraph::io::RdfFormat::TriG), Vec::new())
            .map_err(|e| format!("dump: {e}"))
    }
}

impl Engine for Embedded {
    fn select(&self, query: &str) -> Result<Vec<Map<String, Value>>, String> {
        use oxigraph::model::Term;
        use oxigraph::sparql::{QueryResults, SparqlEvaluator};
        let results = SparqlEvaluator::new().parse_query(query).map_err(|e| format!("store: {e}"))?
            .on_store(&self.store).execute().map_err(|e| format!("store: {e}"))?;
        let mut out = Vec::new();
        if let QueryResults::Solutions(solutions) = results {
            for s in solutions {
                let s = s.map_err(|e| format!("store: {e}"))?;
                let mut row = Map::new();
                for (v, t) in s.iter() {
                    let (ty, val) = match t {
                        Term::NamedNode(n) => ("uri", n.as_str().to_string()),
                        Term::Literal(l) => ("literal", l.value().to_string()),
                        other => ("bnode", other.to_string()),
                    };
                    row.insert(v.as_str().to_string(), json!({ "type": ty, "value": val }));
                }
                out.push(row);
            }
        }
        Ok(out)
    }
    fn update(&self, update: &str) -> Result<(), String> {
        oxigraph::sparql::SparqlEvaluator::new().parse_update(update).map_err(|e| format!("store: {e}"))?
            .on_store(&self.store).execute().map_err(|e| format!("store: {e}"))
    }
    fn as_embedded(&self) -> Option<&Embedded> {
        Some(self)
    }
}

/// The engine settings pick, shared by the row store and the sign-in checker (#4524).
pub fn open_engine(s: &Settings) -> std::sync::Arc<dyn Engine> {
    match s.store_kind.as_str() {
        "sparql" => std::sync::Arc::new(Remote { endpoint: s.store_endpoint.clone(), auth: s.store_auth() }),
        "door" => {
            // #4716 (Silas, demo review) — no token, no start: a door store that
            // came up without one would refuse every write at run time instead
            let d = Door { reads: Remote { endpoint: s.store_endpoint.clone(), auth: None }, door: s.store_door.clone(),
                           token: String::new(), token_command: s.store_token_command.clone() };
            if d.current_token().trim().is_empty() {
                eprintln!("{}: store kind 'door' needs a service token from `{}`; refusing to start", crate::model::PRODUCT, s.store_token_command);
                std::process::exit(2);
            }
            std::sync::Arc::new(d)
        }
        "embedded" => match Embedded::open(&s.store_path) {
            Ok(e) => std::sync::Arc::new(e),
            Err(m) => {
                eprintln!("{}: {m}; refusing to start", crate::model::PRODUCT);
                std::process::exit(2);
            }
        },
        other => {
            eprintln!("{}: store kind '{other}' is not one of sparql, embedded, door; refusing to start", crate::model::PRODUCT);
            std::process::exit(2);
        }
    }
}

pub fn open(s: &Settings) -> Box<dyn RowStore> {
    Box::new(Sparql { engine: open_engine(s) })
}

/// The row store over any SPARQL engine.
pub struct Sparql {
    engine: std::sync::Arc<dyn Engine>,
}

impl Sparql {
    pub fn over(engine: Box<dyn Engine>) -> Self {
        Sparql { engine: std::sync::Arc::from(engine) }
    }
    pub fn shared(engine: std::sync::Arc<dyn Engine>) -> Self {
        Sparql { engine }
    }
    pub fn engine(&self) -> &dyn Engine {
        self.engine.as_ref()
    }
    pub fn embedded(&self) -> Option<&Embedded> {
        self.engine.as_embedded()
    }
}

fn b64(bytes: &[u8]) -> String {
    const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::new();
    for chunk in bytes.chunks(3) {
        let b = [chunk[0], *chunk.get(1).unwrap_or(&0), *chunk.get(2).unwrap_or(&0)];
        let n = (u32::from(b[0]) << 16) | (u32::from(b[1]) << 8) | u32::from(b[2]);
        for i in 0..4 {
            if i <= chunk.len() {
                out.push(char::from(T[((n >> (18 - 6 * i)) & 63) as usize]));
            } else {
                out.push('=');
            }
        }
    }
    out
}

fn local(v: &str) -> String {
    v.rsplit(['#', '/']).next().unwrap_or(v).to_string()
}

/// One SELECT against a remote SPARQL endpoint, as the raw SPARQL-JSON body.
pub fn sparql_update(endpoint: &str, auth: &Option<(String, String)>, update: &str) -> Result<(), String> {
    let mut req = ureq::post(&format!("{}/update", endpoint.trim_end_matches('/')));
    if let Some((u, p)) = auth {
        req = req.set("Authorization", &format!("Basic {}", b64(format!("{u}:{p}").as_bytes())));
    }
    req.send_form(&[("update", update)]).map(|_| ()).map_err(|e| format!("store: {e}"))
}

pub fn sparql_body(endpoint: &str, auth: &Option<(String, String)>, query: &str) -> Result<String, String> {
    let mut req = ureq::post(&format!("{}/query", endpoint.trim_end_matches('/')))
        .set("Accept", "application/sparql-results+json");
    if let Some((u, p)) = auth {
        req = req.set("Authorization", &format!("Basic {}", b64(format!("{u}:{p}").as_bytes())));
    }
    let resp = req.send_form(&[("query", query)]).map_err(|e| format!("store: {e}"))?;
    resp.into_string().map_err(|e| format!("store: {e}"))
}

impl Sparql {
    fn select(&self, query: &str) -> Result<Vec<Map<String, Value>>, String> {
        self.engine.select(query)
    }

    fn rows(&self, class: &ClassDef, subjects: &[String]) -> Result<Vec<Row>, String> {
        if subjects.is_empty() {
            return Ok(Vec::new());
        }
        let values: String = subjects.iter().map(|s| format!("<{s}> ")).collect();
        let q = format!(
            "SELECT ?s ?p ?o WHERE {{ VALUES ?s {{ {values}}} GRAPH <{g}> {{ ?s ?p ?o }} }}",
            g = class.graph
        );
        let triples = self.select(&q)?;
        let mut out = Vec::new();
        for s in subjects {
            let mut row = Row::new();
            row.insert("name".into(), json!(name_of(class, s)));
            let vals = |pred: &str| -> Vec<String> {
                triples.iter()
                    .filter(|t| t["s"]["value"] == json!(s) && t["p"]["value"] == json!(pred))
                    .map(|t| {
                        let v = t["o"]["value"].as_str().unwrap_or("").to_string();
                        if t["o"]["type"] == json!("uri") { local(&v) } else { v }
                    })
                    .collect()
            };
            row.insert("label".into(), json!(vals(&format!("{NS}label")).into_iter().next().unwrap_or_default()));
            row.insert("status".into(), json!(vals(&format!("{NS}status")).into_iter().next().unwrap_or_default()));
            for f in class.fields {
                let mut v = vals(&format!("{NS}{}", f.name));
                v.sort();
                let value = if f.many { json!(v) } else { json!(v.into_iter().next().unwrap_or_default()) };
                row.insert(f.name.into(), value);
            }
            out.push(row);
        }
        Ok(out)
    }
}

impl Sparql {
    /// #4716 — the predicates a row has now, for a door write that replaces it whole.
    fn predicates(&self, graph: &str, subject: &str) -> Result<Vec<String>, String> {
        let rows = self.engine.select(&format!("SELECT DISTINCT ?p WHERE {{ GRAPH <{graph}> {{ <{subject}> ?p ?o }} }}"))?;
        Ok(rows.iter().filter_map(|r| r.get("p").and_then(|v| v["value"].as_str()).map(String::from)).collect())
    }
}

impl RowStore for Sparql {
    fn list(&self, class: &ClassDef, limit: usize, offset: usize) -> Result<(Vec<Row>, usize), String> {
        let count = self.select(&format!(
            "SELECT (COUNT(DISTINCT ?s) AS ?n) WHERE {{ GRAPH <{g}> {{ ?s a <{NS}{c}> }} }}",
            g = class.graph, c = class.name
        ))?;
        let total = count.first().and_then(|r| r["n"]["value"].as_str()).and_then(|n| n.parse().ok()).unwrap_or(0);
        let page = self.select(&format!(
            // #4493 benchmark, 834,316 rows on embedded Oxigraph: ORDER BY ?s made every page
            // a full sort (37 s); the store's own index order serves the same page in 0.4 s,
            // and it is stable while the graph does not change. Rows inside a page are sorted below.
            "SELECT DISTINCT ?s WHERE {{ GRAPH <{g}> {{ ?s a <{NS}{c}> }} }} LIMIT {limit} OFFSET {offset}",
            g = class.graph, c = class.name
        ))?;
        let mut subjects: Vec<String> = page.iter().filter_map(|r| r["s"]["value"].as_str().map(String::from)).collect();
        subjects.sort();
        Ok((self.rows(class, &subjects)?, total))
    }

    fn list_seen_by(&self, class: &ClassDef, limit: usize, offset: usize, viewer: &str) -> Result<(Vec<Row>, usize), String> {
        let (g, c, f) = (class.graph, class.name, seen_by(viewer, class.graph));
        let count = self.select(&format!("SELECT (COUNT(DISTINCT ?s) AS ?n) WHERE {{ GRAPH <{g}> {{ ?s a <{NS}{c}> }} {f} }}"))?;
        let total = count.first().and_then(|r| r["n"]["value"].as_str()).and_then(|n| n.parse().ok()).unwrap_or(0);
        let page = self.select(&format!("SELECT DISTINCT ?s WHERE {{ GRAPH <{g}> {{ ?s a <{NS}{c}> }} {f} }} LIMIT {limit} OFFSET {offset}"))?;
        let mut subjects: Vec<String> = page.iter().filter_map(|r| r["s"]["value"].as_str().map(String::from)).collect();
        subjects.sort();
        Ok((self.rows(class, &subjects)?, total))
    }

    fn list_where(&self, class: &ClassDef, limit: usize, offset: usize, viewer: Option<&str>, w: &Where) -> Result<(Vec<Row>, usize), String> {
        let (g, c) = (class.graph, class.name);
        let f = format!("{} {}", viewer.map(|v| seen_by(v, g)).unwrap_or_default(), where_pattern(w, g));
        let count = self.select(&format!("SELECT (COUNT(DISTINCT ?s) AS ?n) WHERE {{ GRAPH <{g}> {{ ?s a <{NS}{c}> }} {f} }}"))?;
        let total = count.first().and_then(|r| r["n"]["value"].as_str()).and_then(|n| n.parse().ok()).unwrap_or(0);
        // a sorted read keeps the store's order; an unsorted page is sorted by name, as list does
        let order = match &w.sort { Some((_, true)) => "ORDER BY DESC(STR(?ord)) ?s", Some((_, false)) => "ORDER BY STR(?ord) ?s", None => "" };
        let page = self.select(&format!("SELECT DISTINCT ?s ?ord WHERE {{ GRAPH <{g}> {{ ?s a <{NS}{c}> }} {f} }} {order} LIMIT {limit} OFFSET {offset}"))?;
        let mut subjects: Vec<String> = Vec::new();
        for r in &page {
            if let Some(s) = r["s"]["value"].as_str() {
                if !subjects.iter().any(|x| x == s) { subjects.push(s.to_string()); }
            }
        }
        if w.sort.is_none() { subjects.sort(); }
        let mut rows = self.rows(class, &subjects)?;
        if w.sort.is_some() {
            let pos = |r: &Row| subjects.iter().position(|s| r.get("name").and_then(|n| n.as_str()).is_some_and(|n| *s == iri(class, n)));
            rows.sort_by_key(|r| pos(r));
        }
        Ok((rows, total))
    }

    fn get_seen_by(&self, class: &ClassDef, name: &str, viewer: &str) -> Result<Option<Row>, String> {
        let s = iri(class, name);
        let (g, c, f) = (class.graph, class.name, seen_by(viewer, class.graph));
        let hit = self.select(&format!("SELECT ?s WHERE {{ BIND(<{s}> AS ?s) GRAPH <{g}> {{ ?s a <{NS}{c}> }} {f} }} LIMIT 1"))?;
        if hit.is_empty() {
            return Ok(None);
        }
        Ok(self.rows(class, &[s])?.into_iter().next())
    }

    fn get(&self, class: &ClassDef, name: &str) -> Result<Option<Row>, String> {
        let s = iri(class, name);
        let hit = self.select(&format!(
            "SELECT ?s WHERE {{ GRAPH <{g}> {{ <{s}> a <{NS}{c}> . BIND(<{s}> AS ?s) }} }} LIMIT 1",
            g = class.graph, c = class.name
        ))?;
        if hit.is_empty() {
            return Ok(None);
        }
        Ok(self.rows(class, &[s])?.into_iter().next())
    }

    fn exists(&self, iri: &str) -> Result<bool, String> {
        Ok(!self.select(&format!("SELECT ?p WHERE {{ GRAPH ?g {{ <{iri}> ?p ?o }} }} LIMIT 1"))?.is_empty())
    }

    fn version_count(&self, of_row: &str) -> Result<usize, String> {
        let lit = of_row.replace('"', "");
        let r = self.select(&format!(
            "SELECT (COUNT(?v) AS ?n) WHERE {{ GRAPH <{GRAPH_PREFIX}provenance> {{ ?v <{NS}ofRow> \"{lit}\" }} }}"))?;
        Ok(r.first().and_then(|x| x["n"]["value"].as_str()).and_then(|n| n.parse().ok()).unwrap_or(0))
    }

    fn write(&self, graph: &str, subject: &str, type_of: Option<&str>, fields: &[(String, Vec<Cell>)], whole: bool) -> Result<(), String> {
        if let Some(d) = self.engine.as_door() {
            let existing = if whole { self.predicates(graph, subject)? } else { Vec::new() };
            return d.batch(graph, &write_lines(subject, type_of, fields, whole, &existing));
        }
        self.engine.update(&write_update(graph, subject, type_of, fields, whole))
    }

    fn delete(&self, graph: &str, subject: &str) -> Result<(), String> {
        if let Some(d) = self.engine.as_door() {
            let existing = self.predicates(graph, subject)?;
            return d.batch(graph, &write_lines(subject, None, &[], true, &existing));
        }
        self.engine.update(&format!("DELETE WHERE {{ GRAPH <{graph}> {{ <{subject}> ?p ?o }} }}"))
    }
}
